UPDATE spots SET lat = 35.631974, lng = 139.742992, description = '品川駅港南口エリアを起点に芝浦ふ頭へ進み、レインボーブリッジの遊歩道(約1.7km)で東京湾を渡ってお台場へ。お台場海浜公園からシンボルプロムナード、ダイバーシティ前を回り、同じ遊歩道で戻る約16.5kmの周回。橋上からは都心と湾岸のパノラマが広がり夜景も見事。遊歩道は開放時間制(4-10月9-21時・11-3月10-18時、第3月曜休)で通行無料・自転車走行不可。', access = 'JR品川駅港南口から約1km/ゆりかもめお台場海浜公園駅', updated_at = unixepoch() * 1000 WHERE id = '19ab63f0-f4e2-4571-91e2-a04766cfdff0' AND lat IS 35.6319752 AND lng IS 139.7429829 AND description IS '品川駅港南口エリアから街路の歩道を進み、芝浦側の入口とエレベーターでレインボーブリッジの遊歩道へ。往路はサウスルート、復路はノースルートを使い、お台場海浜公園、ウエストプロムナード、ダイバーシティ前の屋外広場、センタープロムナードをつなぐ約12.6kmの参考ルートです。橋の遊歩道や階段、混雑する広場では歩いて通過し、歩行者を優先してください。' AND access IS '参考起点は品川駅港南口エリアの歩道です。芝浦ふ頭駅・お台場海浜公園駅から合流する場合は、歩行者用入口と現地の案内を確認してください。';
